'use client'

import { useEffect, useState } from 'react'
import { useRouter } from 'next/navigation'
import Link from 'next/link'
import { Utensils, Package, BedDouble, HandHelping, TrendingUp, ChevronRight } from 'lucide-react'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { useAuth } from '@/contexts/AuthContext'

interface Resource {
  _id: string
  name: string
  totalQuantity: number
  distributedQuantity: number
  type: string
}

export default function VolunteerDashboard() {
  const { user, loading } = useAuth()
  const router = useRouter()
  const [resources, setResources] = useState<Resource[]>([])
  const [filter, setFilter] = useState('all')

  useEffect(() => {
    if (!loading && (!user || (user.role !== 'volunteer' && user.role !== 'admin'))) {
      router.push('/login')
    }
  }, [user, loading, router])

  useEffect(() => {
    fetchResources()
  }, [])

  const fetchResources = async () => {
    try {
      const res = await fetch('/api/resources')
      const data = await res.json()
      setResources(data.resources)
    } catch (error) {
      console.error('Failed to fetch resources:', error)
    }
  }

  if (loading || !user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <p>Loading...</p>
      </div>
    )
  }

  // Group resources by type
  const foodResources = resources.filter(r => r.name.toLowerCase().includes('lunch') || r.name.toLowerCase().includes('dinner') || r.name.toLowerCase().includes('breakfast') || r.name.toLowerCase().includes('food'))
  const bagResources = resources.filter(r => r.name.toLowerCase().includes('bag') || r.name.toLowerCase().includes('sleep'))
  const chillResources = resources.filter(r => r.name.toLowerCase().includes('chill'))

  const getFilteredResources = () => {
    switch (filter) {
      case 'food': return foodResources
      case 'bag': return bagResources
      case 'chill': return chillResources
      default: return [...foodResources, ...bagResources, ...chillResources]
    }
  }

  const getResourceRoute = (name: string) => {
    const lowerName = name.toLowerCase()
    if (lowerName.includes('lunch') || lowerName.includes('dinner') || lowerName.includes('breakfast') || lowerName.includes('food')) return '/volunteer/scan-food'
    if (lowerName.includes('bag') || lowerName.includes('sleep')) return '/volunteer/scan-bag'
    if (lowerName.includes('chill')) return '/volunteer/scan-chill'
    return '/volunteer'
  }

  const getResourceIcon = (name: string) => {
    const lowerName = name.toLowerCase()
    if (lowerName.includes('lunch') || lowerName.includes('dinner') || lowerName.includes('breakfast') || lowerName.includes('food')) return Utensils
    if (lowerName.includes('bag') || lowerName.includes('sleep')) return BedDouble
    if (lowerName.includes('chill')) return Package
    return Package
  }

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold text-foreground">Volunteer Dashboard</h1>
          <p className="text-muted-foreground">Manage resources and track distribution</p>
        </div>
        <div className="flex gap-2 bg-secondary/50 p-1 rounded-lg">
          {['all', 'food', 'bag', 'chill'].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${filter === f
                  ? 'bg-primary text-primary-foreground shadow-sm'
                  : 'text-muted-foreground hover:text-foreground hover:bg-secondary'
                }`}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)}
            </button>
          ))}
        </div>
      </div>

      {/* Quick Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <Card>
          <CardHeader className="pb-2">
            <CardDescription>Total Distributed</CardDescription>
            <CardTitle className="text-2xl">
              {resources.reduce((sum, r) => sum + r.distributedQuantity, 0)}
            </CardTitle>
          </CardHeader>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardDescription>Food Served</CardDescription>
            <CardTitle className="text-2xl">
              {foodResources.reduce((sum, r) => sum + r.distributedQuantity, 0)}
            </CardTitle>
          </CardHeader>
        </Card>
        <Card>
          <CardHeader className="pb-2">
            <CardDescription>Bags Issued</CardDescription>
            <CardTitle className="text-2xl">
              {bagResources.reduce((sum, r) => sum + r.distributedQuantity, 0)}
            </CardTitle>
          </CardHeader>
        </Card>
        <Link href="/volunteer/help">
          <Card className="hover:bg-secondary/50 transition-colors cursor-pointer h-full border-primary/20">
            <CardHeader className="pb-2">
              <CardDescription className="text-primary">Help Desk</CardDescription>
              <CardTitle className="text-xl flex items-center gap-2 text-primary">
                <HandHelping className="h-5 w-5" />
                Manage Requests
              </CardTitle>
            </CardHeader>
          </Card>
        </Link>
      </div>

      {/* Resources Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {getFilteredResources().map((resource) => {
          const Icon = getResourceIcon(resource.name)
          const route = getResourceRoute(resource.name)

          return (
            <Link key={resource._id} href={route}>
              <Card className="hover:bg-secondary/50 transition-all cursor-pointer hover:border-primary/50 group h-full">
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                  <CardTitle className="text-lg font-medium group-hover:text-primary transition-colors">
                    {resource.name}
                  </CardTitle>
                  <Icon className="h-5 w-5 text-muted-foreground group-hover:text-primary transition-colors" />
                </CardHeader>
                <CardContent>
                  <div className="space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-muted-foreground">Distributed</span>
                      <span className="font-medium">{resource.distributedQuantity} / {resource.totalQuantity}</span>
                    </div>
                    <div className="h-2 bg-secondary rounded-full overflow-hidden">
                      <div
                        className="h-full bg-primary transition-all duration-500"
                        style={{ width: `${(resource.distributedQuantity / resource.totalQuantity) * 100}%` }}
                      />
                    </div>
                    <div className="flex items-center justify-end gap-1 text-xs text-primary opacity-0 group-hover:opacity-100 transition-opacity">
                      <span>Scan Now</span>
                      <ChevronRight className="h-3 w-3" />
                    </div>
                  </div>
                </CardContent>
              </Card>
            </Link>
          )
        })}
      </div>
    </div>
  )
}
